u16 TMHMGetMove(u16 itemId) {
    if (itemId < ITEM_TM01 || itemId > ITEM_HM08) {
        return MOVE_NONE;
    }

    itemId -= ITEM_TM01;
    return sTMHMMoves[itemId];
}

// Everything that asks this asks it for one reason: to refuse to let the move
// be forgotten. New Gold lets them be forgotten, so the answer is always no.
// The move deleter, the summary and the party menu all reach it through this
// one function, so this is the whole of the change.
//
// Whether a move came from a machine is a different question, and the one
// place that wanted that asks ItemIsMachine about the item instead.
BOOL MoveIsHM(u16 moveId) {
#pragma unused(moveId)
    return FALSE;
}

BOOL ItemIsTM(u16 itemId) {
    return itemId >= ITEM_TM01 && itemId <= ITEM_TM92;
}

BOOL ItemIsMachine(u16 itemId) {
    return itemId >= ITEM_TM01 && itemId <= ITEM_HM08;
}

u8 ItemToTMHMId(u16 itemId) {
    if (itemId < ITEM_TM01 || itemId > ITEM_HM08) {
        return 0;
    }

    return itemId - ITEM_TM01;
}

BOOL ItemIdIsMail(u16 itemId) {
    if (itemId < FIRST_MAIL_IDX || itemId > LAST_MAIL_IDX) {
        return FALSE;
    } else {
        return TRUE;
    }
}

u8 ItemToMailId(u16 itemId) {
    if (itemId < FIRST_MAIL_IDX || itemId > LAST_MAIL_IDX) {
        return 0;
    } else {
        return itemId - ITEM_GRASS_MAIL + MAIL_GRASS;
    }
}

u16 MailToItemId(u8 mailId) {
    if (mailId >= NUM_MAIL) {
        return ITEM_NONE;
    } else {
        return mailId - MAIL_GRASS + ITEM_GRASS_MAIL;
    }
}

s32 ItemToBallId(u16 itemId) {
    if (itemId >= ITEM_MASTER_BALL && itemId <= ITEM_CHERISH_BALL) {
        return itemId - ITEM_MASTER_BALL + BALL_MASTER;
    } else if (itemId >= ITEM_FAST_BALL && itemId <= ITEM_SPORT_BALL) {
        return itemId - ITEM_FAST_BALL + BALL_FAST;
    } else {
        return BALL_POKE;
    }
}

u16 BallToItemId(s32 ballId) {
    if (ballId >= BALL_MASTER && ballId <= BALL_CHERISH) {
        return ballId - BALL_MASTER + ITEM_MASTER_BALL;
    } else if (ballId >= BALL_FAST && ballId <= BALL_SPORT) {
        return ballId - BALL_FAST + ITEM_FAST_BALL;
    } else {
        return ITEM_POKE_BALL;
    }
}

BOOL ItemIdIsBerry(u16 itemId) {
    if (itemId < FIRST_BERRY_IDX || itemId > LAST_BERRY_IDX) {
        return FALSE;
    } else {
        return TRUE;
    }
}

u16 BerryToItemId(u8 berryId) {
    if (berryId >= NUM_BERRIES) {
        return 0xFFFF;
    }
    return (u16)(berryId + FIRST_BERRY_IDX);
}

String *GetNutName(u16 berryId, enum HeapID heapID) {
    String *ret;
    MsgData *msgData;

    if (berryId != 0) {
        berryId--;
    }
    msgData = NewMsgDataFromNarc(MSGDATA_LOAD_LAZY, NARC_msgdata_msg, NARC_msg_msg_0251_bin, heapID);
    ret = NewString_ReadMsgData(msgData, berryId);
    DestroyMsgData(msgData);
    return ret;
}

ItemData *LoadAllItemData(enum HeapID heapID) {
    // The battle indexes this array by an item's own data member, so the last
    // item's record has to be inside it: the mapping gives that member's
    // number, and a count is one more than the last number. HeartGold left the
    // plus one out and never noticed, because the last item it had was the
    // Enigma Stone and nothing carries a key item into a battle. New Gold's
    // last item is the Snowball, which a wild Pokemon holds.
    //
    // This is also the one allocation in the game that the item range sizes,
    // and it grew with it: this port asked the battle heap for 0x4C14 here and
    // the whole of konefr's range asks for 0x17778, out of the 0xB0000 that
    // Battle_Run carves. That is still a small part of it, but it is no
    // longer a rounding error, and heap 3 has no room to widen the battle's
    // share -- tests/newgold/test_heaps.py holds the margin retail had.
    // So tests/newgold/test_heaps.py holds a ceiling on this one too.
    return AllocAndReadFromNarcMemberByIdPair(NARC_itemtool_itemdata_item_data, 0, heapID, 0, (GetItemIndexMapping(ITEM_MAX, ITEMNARC_PARAM) + 1) * sizeof(ItemData));
}

ItemData *GetItemDataPtrFromArray(ItemData *itemData, u32 itemDataIdx) {
    return &itemData[itemDataIdx];
}

BOOL ItemIdIsNotJohtoBall(u16 itemId) {
    // stupid hack to get it to match
    if ((u16)(itemId + (u16)-ITEM_FAST_BALL) > (ITEM_PARK_BALL - ITEM_FAST_BALL)) {
        return TRUE;
    } else {
        return FALSE;
    }
}
